package inspect

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"bint/internal/testutil"
)

func TestInspect(t *testing.T) {
	root := testutil.NewRepo(t, map[string]string{
		"go.mod":                   "module demo\n\ngo 1.22\n\nrequire (\n\tgithub.com/a/b v1.0.0\n\tgithub.com/c/d v1.0.0 // indirect\n)\n",
		"go.sum":                   "",
		"web/package.json":         `{"dependencies":{"react":"18"},"devDependencies":{"vitest":"1"},"scripts":{"test":"vitest","build":"vite build"}}`,
		"main.go":                  "package main\n",
		"api/gen/api.pb.go":        "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage gen\n",
		"Makefile":                 "proto:\n\tbuf generate\n.PHONY: proto\n",
		".github/workflows/ci.yml": "on: push\n",
		"CONTRIBUTING.md":          "x",
		"CLAUDE.md":                "x",
		"vendor/x/y.go":            "package y\n",
	})
	for i, msg := range []string{"fix: race in main", "Revert \"feature\"", "fix crash in main"} {
		os.WriteFile(filepath.Join(root, "main.go"), []byte("package main\n// "+msg+string(rune('a'+i))+"\n"), 0o644)
		testutil.Git(t, root, "commit", "-qam", msg)
	}
	rep, err := Inspect(context.Background(), root, Options{})
	if err != nil {
		t.Fatal(err)
	}
	if len(rep.Languages) == 0 || rep.Languages[0].Name != "Go" || rep.Languages[0].Files != 2 {
		t.Errorf("ngôn ngữ (không tính vendor): %+v", rep.Languages)
	}
	var gomod, pkg *Manifest
	for i := range rep.Manifests {
		switch rep.Manifests[i].Path {
		case "go.mod":
			gomod = &rep.Manifests[i]
		case "web/package.json":
			pkg = &rep.Manifests[i]
		}
	}
	if gomod == nil || gomod.Lockfile != "go.sum" || len(gomod.Dependencies) != 1 || gomod.Dependencies[0] != "github.com/a/b" {
		t.Errorf("go.mod: %+v", gomod)
	}
	if pkg == nil || len(pkg.Dependencies) != 1 || len(pkg.DevDeps) != 1 || len(pkg.Scripts) != 2 {
		t.Errorf("package.json: %+v", pkg)
	}
	has := func(name string) bool {
		for _, c := range rep.Commands {
			if c.Name == name {
				return true
			}
		}
		return false
	}
	if !has("make:proto") || has("make:.PHONY") || !has("npm:build") {
		t.Errorf("lệnh: %+v", rep.Commands)
	}
	if len(rep.Generated) != 1 || rep.Generated[0].Dir != "api/gen" {
		t.Errorf("mã sinh: %+v", rep.Generated)
	}
	kinds := map[string]bool{}
	for _, d := range rep.Docs {
		kinds[d.Kind] = true
	}
	if !kinds["contributing"] || !kinds["agents"] {
		t.Errorf("tài liệu: %+v", rep.Docs)
	}
	if rep.Git.Commits != 4 || len(rep.Git.Reverts) != 1 || len(rep.Git.FixCommits) != 2 ||
		len(rep.Git.FixHotspots) == 0 || rep.Git.FixHotspots[0].Path != "main.go" {
		t.Errorf("git: %+v", rep.Git)
	}
	ci := false
	for _, tl := range rep.Tools {
		ci = ci || tl.Kind == "ci"
	}
	if !ci {
		t.Errorf("thiếu CI: %+v", rep.Tools)
	}
}
